import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:meditag/tag/envelope.dart';
import 'package:meditag/tag/payload.dart';

// Shared with the server and the website; generated by `npm --prefix functions run vectors`.
final vectors = jsonDecode(File('../schema/test-vectors.json').readAsStringSync()) as Map<String, dynamic>;
final keys = {1: hexToBytes(vectors['publicKeyHex'] as String)};
Map<String, dynamic> vector(String name) =>
    (vectors['cases'] as List<dynamic>).cast<Map<String, dynamic>>().firstWhere((c) => c['name'] == name);

void main() {
  group('readEnvelope (shared test vectors)', () {
    test('verifies a genuine tag', () {
      final result = readEnvelope(hexToBytes(vector('valid')['envelopeHex'] as String), keys);
      expect(result, isA<ReadOk>());
      final ok = result as ReadOk;
      expect(ok.trust, TagTrust.verified);
      final expected = vector('valid')['expectPayload'] as Map<String, dynamic>;
      expect(ok.payload.name, expected['n']);
      expect(ok.payload.bloodGroup, expected['bg']);
      expect(ok.payload.allergies, expected['al']);
      expect(ok.payload.contacts.first.phone, '+919876543210');
    });

    test('flags an edited blood group as unverified but still shows it', () {
      final result = readEnvelope(hexToBytes(vector('tampered-blood-group')['envelopeHex'] as String), keys) as ReadOk;
      expect(result.trust, TagTrust.unverified);
      expect(result.payload.bloodGroup, 'O+');
    });

    test('flags a tag signed by someone else', () {
      final result = readEnvelope(hexToBytes(vector('signed-by-other-key')['envelopeHex'] as String), keys) as ReadOk;
      expect(result.trust, TagTrust.unverified);
    });

    test('treats unknown key ids as unverified', () {
      final result = readEnvelope(hexToBytes(vector('valid')['envelopeHex'] as String), {}) as ReadOk;
      expect(result.trust, TagTrust.unverified);
    });

    test('reports truncated data as unreadable', () {
      final result = readEnvelope(hexToBytes(vector('truncated')['envelopeHex'] as String), keys);
      expect(result, isA<ReadUnreadable>());
    });
  });

  group('TagPayload', () {
    final now = DateTime(2026, 10, 31);
    final signedAt = DateTime.utc(2026);
    final p = TagPayload(tagId: 'x', name: 'Rahul Sharma', signedAt: signedAt, dob: '1998-04-12', sex: 'M', organDonor: true);

    test('computes age around birthdays', () {
      expect(p.ageOn(now), 28);
      expect(TagPayload(tagId: 'x', name: 'A', signedAt: signedAt, dob: '1998-11-30').ageOn(now), 27);
    });

    test('describes a person compactly', () => expect(p.describe(now), '28 yrs · Male · Organ donor'));

    test('makes initials', () => expect(p.initials, 'RS'));

    test('rejects non-MediTag JSON', () {
      expect(() => TagPayload.fromJson({'v': 2, 'n': 'A', 'tid': 'x', 'ts': 1}), throwsFormatException);
    });
  });
}
